// Shapes of public/data/game.json (generated by tools/gen_data.py).

export type ShipCategory = "Raw" | "Manufactured" | "Encoded";
export type LockerCategory = "Item" | "Component" | "Data" | "Consumable";

export interface Material {
  id: string;
  name: string;
  ledger: "ship" | "locker";
  category: ShipCategory | LockerCategory;
  grade?: number;
  line?: string;
  origins: string[];
  methods: string[];
  settlements?: string[];
  buildings?: string[];
  containers?: string[];
  barter?: string;
}

export interface Effect {
  label: string;
  value: string;
  good: boolean;
}

export type BlueprintKind =
  | "modification"
  | "experimental"
  | "synthesis"
  | "tech-broker"
  | "suit"
  | "weapon"
  | "merchant"
  | "unlock"
  | "bartender";

export interface Blueprint {
  kind: BlueprintKind;
  module: string;
  name: string;
  grade?: number;
  engineers?: string[];
  ingredients: Record<string, number>;
  effects?: Effect[];
}

export interface Engineer {
  id: number;
  name: string;
  system: string;
  station: string;
  body: string;
  pos: [number, number, number] | null;
  odyssey: boolean;
  specialities: { name: string; grade: number }[];
  discovery: string;
  meeting: string;
  unlock: string;
  referredBy: string;
}

export interface FixedSite {
  system: string;
  pos: [number, number, number];
  body: string;
  what: string;
  materials: string[];
  lat?: number;
  lon?: number;
}

export interface GameData {
  materials: Material[];
  lines: Record<string, string>;
  blueprints: Blueprint[];
  engineers: Engineer[];
  sites: FixedSite[];
  credits: string;
}
